B.F3=new A.c6("compare_options","Compare Your Options","- Consider what will lead to the least trouble, even if it\u2019s not what you feel like doing","assets/videos/level_4_6/compare_your_options.mp4")
B.F4=new A.c6("get_in_the_zone","Get in the Zone!","- Try to fully participate in whatever you are doing","assets/videos/level_1_3/get_in_the_zone.mp4")
B.F5=new A.c6("distract_yourself","Distract Yourself","- Do something that grabs your attention away from stress","assets/videos/level_7_8/distract_yourself.mp4")
B.F6=new A.c6("let_emotions_flow","Let Your Emotions Flow","- Don\u2019t try to push away or hold onto your emotions, just allow them to be","assets/videos/level_4_6/let_your_emotions_flow.mp4")
B.F7=new A.c6("help_out_someone_else","Help Out Someone Else","- You\u2019ll focus more on their situation than your own","assets/videos/level_7_8/help_someone_else.mp4")
B.F8=new A.c6("check_thoughts_feelings","Check Your Thoughts and Feelings","- Thoughts and feelings can lie, check to see if they really match the situation","assets/videos/level_4_6/check_your_thoughts.mp4")
B.F9=new A.c6("recognize_feelings","Recognize Feelings","- Tell yourself (or someone else) why your (or their) emotions make sense","assets/videos/level_4_6/recognize_your_feelings.mp4")
B.Fa=new A.c6("do_something_fun","Do Something Fun","- Build up your tank of wanted emotions","assets/videos/level_1_3/do_something_fun.mp4")
B.Fb=new A.c6("cold_shock","Cold Shock","- Help the brain reset: ice pack on face or dunk head in cold water","assets/videos/level_9_10/cold_shock.mp4")
B.Fc=new A.c6("label_what_you_notice","Label What You Notice","- Say in your thoughts (or out loud) things you notice inside and out","assets/videos/level_1_3/label_what_you_notice.mp4")
B.Fd=new A.c6("consider_others_pov","Consider Others\u2019 Point of View","- Imagine what thoughts/feelings are behind someone else\u2019s words/actions","assets/videos/level_4_6/others_point_of_view.mp4")
B.Fe=new A.c6("use_your_5_senses","Use Your 5 Senses","- Comforting (ex: blanket) or intense things (ex: sour candy), or just name objects in the room","assets/videos/level_7_8/5_senses.mp4")
B.Ff=new A.c6("burst_of_exercise","Burst of Exercise","- One minute to get your heart beating!","assets/videos/level_9_10/burst_of_exercise.mp4")
B.Fg=new A.c6("imagine_calm_safe_place","Imagine a Calm or Safe Place","- Think of a real or pretend place that feels calm","assets/videos/level_7_8/a_calm_place.mp4")
B.Fh=new A.c6("problem_solve","Problem Solve","- Brainstorm as many ideas as you can before you try one","assets/videos/level_4_6/try_problem_solving.mp4")
B.Fi=new A.c6("take_a_break_walk_away","Take a Break / Walk Away","- Step away from the stressful situation for a few minutes","assets/videos/level_7_8/take_a_break.mp4")
